        for (int j = 0; j < 65; ++j) initv[j] = static_cast<uint16_t>(CM_squash((j - 32) * 64) * 16);
        for (int i = 0; i < 32768; ++i)
            for (int j = 0; j < 65; ++j) apm[i * 65 + j] = initv[j];
        for (int i = 0; i < 4096; ++i)
            for (int j = 0; j < 65; ++j) apm2[i * 65 + j] = initv[j];
